using System;
using System.Text;
using UnityEditor;
using UnityEngine;

public class EnumProbe
{
    public static void Run()
    {
        Type t = Type.GetType("TMPro.TextAlignmentOptions, Unity.TextMeshPro");
        StringBuilder sb = new StringBuilder();

        if (t == null)
        {
            Debug.Log("[EnumProbe] type not found");
            return;
        }

        foreach (string name in Enum.GetNames(t))
            sb.Append(name).Append('(').Append(Convert.ToInt32(Enum.Parse(t, name))).Append(") ");

        Debug.Log("[EnumProbe] " + sb);
    }
}
